import React, { useState, useEffect, useCallback } from "react";
import { useParams } from "react-router-dom";
import axios from "axios";
import styled from "styled-components";

const EmployeePage = () => {
  const { id } = useParams();
  const [employeeData, setEmployeeData] = useState({
    name: "",
    phone: "",
    role: "driver",
    salary: ""
  });
  const [employeePhone, setEmployeePhone] = useState("");  // New state variable for phone
  const [employeeSalary, setEmployeeSalary] = useState("");  // New state variable for salary
  const [filteredEmployees, setFilteredEmployees] = useState([]);
  const [isFormVisible, setFormVisible] = useState(false);
  const [isUpdateFormVisible, setUpdateFormVisible] = useState(false);
  const [selectedEmployeeDetails, setSelectedEmployeeDetails] = useState(null);
  const [updateData, setUpdateData] = useState({
    phone: "",
    startDate: "",
    endDate: "",
    expensePaid: ""
  });
  const [loading, setLoading] = useState(false); // For loading state

  const fetchEmployeesByRole = useCallback(
    async (role) => {
      setLoading(true);
      try {
        const response = await axios.get(
          `http://localhost:5001/api/employee/employeesByRole/${id}/${role}`
        );
        setFilteredEmployees(response.data);
      } catch (error) {
        console.error("Error fetching employees:", error);
      } finally {
        setLoading(false);
      }
    },
    [id]
  );

  const handleEmployeeClick = async (phone) => {
    setLoading(true);
    try {
      const response = await axios.get(
        `http://localhost:5001/api/employee/${phone}`
      );
      setSelectedEmployeeDetails(response.data);
    } catch (error) {
      console.error("Error fetching employee details:", error);
      alert("Error fetching employee details");
    } finally {
      setLoading(false);
    }
  };

  const addEmployee = async () => {
    if (!employeeData.name || !employeeData.phone || !employeeData.salary) {
      alert("Please fill all fields.");
      return;
    }

    setLoading(true);
    try {
      const newEmployee = {
        lorry_id: id,
        name: employeeData.name,
        phone: employeeData.phone,
        role: employeeData.role,
        fixed_salary: Number(employeeData.salary),  // Ensure it's a number
      };
      await axios.post(`http://localhost:5001/api/employee/add`, newEmployee);
      alert("Employee added successfully!");
      fetchEmployeesByRole(employeeData.role); // Refresh the list
      setFormVisible(false);
    } catch (error) {
      console.error("Error adding employee:", error);
      alert("Failed to add employee.");
    } finally {
      setLoading(false);
    }
  };

  const handleUpdateEmployee = async () => {
    setLoading(true);
    try {
      const updateDataRequest = {
        phone: updateData.phone,
        startDate: updateData.startDate,
        endDate: updateData.endDate,
        expense: updateData.expensePaid,
      };

      await axios.put(`http://localhost:5001/api/employee/updateExpense`, updateDataRequest);
      alert("Employee expense updated successfully!");
      fetchEmployeesByRole(employeeData.role); // Refresh the list
      setUpdateFormVisible(false);
    } catch (error) {
      console.error("Error updating employee:", error);
      alert("Failed to update employee.");
    } finally {
      setLoading(false);
    }
  };

  const deleteEmployee = async (phone) => {
    setLoading(true);
    try {
      await axios.delete(`http://localhost:5001/api/employee/delete/${phone}`);
      alert("Employee deleted successfully!");
      fetchEmployeesByRole(employeeData.role); // Refresh the list
    } catch (error) {
      console.error("Error deleting employee:", error);
      alert("Failed to delete employee.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchEmployeesByRole(employeeData.role);
  }, [employeeData.role, id, fetchEmployeesByRole]);

  return (
    <Container>
      <Header>
        <LorryTitle>Lorry {id}</LorryTitle>
      </Header>

      <Button onClick={() => setFormVisible(true)}>Add Employee</Button>

      {isFormVisible && (
        <Form>
          <Input
            type="text"
            placeholder="Employee Name"
            value={employeeData.name}
            onChange={(e) => setEmployeeData({ ...employeeData, name: e.target.value })}
          />
          <Input
            type="text"
            placeholder="Phone Number"
            value={employeeData.phone}
            onChange={(e) => setEmployeeData({ ...employeeData, phone: e.target.value })}
          />
          <Select
            value={employeeData.role}
            onChange={(e) => setEmployeeData({ ...employeeData, role: e.target.value })}
          >
            <option value="driver">Driver</option>
            <option value="driller">Driller</option>
            <option value="manager">Manager</option>
            <option value="worker">Worker</option>
          </Select>
          <Input
            type="number"
            placeholder="Fixed Salary"
            value={employeeData.salary}
            onChange={(e) => setEmployeeData({ ...employeeData, salary: e.target.value })}
          />
          <Button onClick={addEmployee} disabled={loading}>
            {loading ? "Adding..." : "Add Employee"}
          </Button>
          <Button onClick={() => setFormVisible(false)}>Cancel</Button>
        </Form>
      )}

      {isUpdateFormVisible && (
        <UpdateForm>
          <Input
            type="text"
            placeholder="Phone Number"
            value={updateData.phone}
            onChange={(e) => setUpdateData({ ...updateData, phone: e.target.value })}
          />
          <Input
            type="date"
            placeholder="Start Date"
            value={updateData.startDate}
            onChange={(e) => setUpdateData({ ...updateData, startDate: e.target.value })}
          />
          <Input
            type="date"
            placeholder="End Date"
            value={updateData.endDate}
            onChange={(e) => setUpdateData({ ...updateData, endDate: e.target.value })}
          />
          <Input
            type="number"
            placeholder="Expense Paid"
            value={updateData.expensePaid}
            onChange={(e) => setUpdateData({ ...updateData, expensePaid: e.target.value })}
          />
          <Button onClick={handleUpdateEmployee} disabled={loading}>
            {loading ? "Updating..." : "Update Expense"}
          </Button>
          <Button onClick={() => setUpdateFormVisible(false)}>Cancel</Button>
        </UpdateForm>
      )}

      <RoleTabs>
        {["driver", "driller", "manager", "worker"].map((role) => (
          <Tab
            key={role}
            onClick={() => setEmployeeData({ ...employeeData, role })}
            $active={employeeData.role === role}
          >
            {role.charAt(0).toUpperCase() + role.slice(1)}
          </Tab>
        ))}
      </RoleTabs>

      {loading ? (
        <p>Loading...</p>
      ) : (
        <EmployeeList>
          {filteredEmployees.map((employee) => (
            <EmployeeItem key={employee.phone}>
              <div onClick={() => handleEmployeeClick(employee.phone)}>
                {employee.name} ({employee.phone})
              </div>
              <Button onClick={() => {
                setUpdateData({ phone: employee.phone });
                setUpdateFormVisible(true);
              }}>
                Update
              </Button>
              <Button onClick={() => deleteEmployee(employee.phone)}>Delete</Button>
              <Button onClick={() => handleEmployeeClick(employee.phone)}>
                Details
              </Button>
            </EmployeeItem>
          ))}
        </EmployeeList>
      )}

      {selectedEmployeeDetails && (
        <DetailsTable>
          <thead>
            <tr>
              <th>Name</th>
              <th>Phone</th>
              <th>Start Date</th>
              <th>End Date</th>
              <th>Expense</th>
            </tr>
          </thead>
          <tbody>
            {selectedEmployeeDetails.salaryRecords.map((record, index) => (
              <tr key={index}>
                <td>{selectedEmployeeDetails.name}</td>
                <td>{selectedEmployeeDetails.phone}</td>
                <td>{record.startDate}</td>
                <td>{record.endDate}</td>
                <td>{record.expense}</td>
              </tr>
            ))}
          </tbody>
        </DetailsTable>
      )}
    </Container>
  );
};

